<script setup lang="ts">
import {ref,onBeforeUnmount,computed} from 'vue'
import WorkbenchCheckbox from './WorkbenchCheckbox.vue'
import WorkbenchSelect from './WorkbenchSelect.vue'
import {chooseFolder} from '../lib/storage'
import {analyzeWithWorker,inspectWithWorker} from '../lib/worker-client'
import {nearestKey} from '../lib/timeline-index.mjs'
import {runContainerInWorker} from '../lib/container-client'
import {workspace} from '../core/workspace'
import {friendlyError,humanBytes} from '../lib/format'
import type {ContainerOutput} from '../lib/container-ops'
const mode=ref<'trim'|'merge'>('trim'),files=ref<File[]>([]),start=ref(0),end=ref(1),busy=ref(false),progress=ref(0),message=ref(''),error=ref(''),result=ref<ContainerOutput[]>([])
let ctrl:AbortController|null=null
const allowAacPreroll=ref(false)
const keys=ref<number[]>([]),duration=ref(0),analyzing=ref(false)
const validRange=computed(()=>keys.value.includes(start.value)&&(keys.value.includes(end.value)||end.value===duration.value)&&end.value>start.value)
async function analyze(){if(!files.value.length||busy.value||analyzing.value)return;const file=files.value[0],ctl=new AbortController();ctrl=ctl;analyzing.value=true;error.value='';try{const info=await workspace.run('inspect',file,ctl.signal,()=>inspectWithWorker(file,ctl.signal));const analysis=await workspace.run('analyze',file,ctl.signal,ctx=>analyzeWithWorker(file,ctl.signal,(p,l)=>ctx.progress(p,l)));if(files.value[0]!==file)return;keys.value=analysis.safeKeyframeIndex;duration.value=info.duration;start.value=keys.value[0]??0;end.value=info.duration}catch(e){error.value=friendlyError(e)}finally{analyzing.value=false;ctrl=null}}
function snap(which:'start'|'end'){const t=which==='start'?start.value:end.value;const key=nearestKey(which==='end'?[...keys.value,duration.value]:keys.value,t);if(key!==undefined){if(which==='start')start.value=key;else end.value=key}}
function pick(){const input=document.createElement('input');input.type='file';input.multiple=mode.value==='merge';input.accept='.mp4,.m4v,.mov';input.onchange=()=>{files.value=Array.from(input.files??[]).slice(0,50);result.value=[];keys.value=[];duration.value=0};input.click()}
function move(i:number,delta:number){const next=i+delta;if(next<0||next>=files.value.length)return;const copy=[...files.value];[copy[i],copy[next]]=[copy[next],copy[i]];files.value=copy}
async function run(){if(busy.value||!files.value.length)return;busy.value=true;error.value='';result.value=[];progress.value=0;const ctl=new AbortController();ctrl=ctl;try{const root=await chooseFolder(),folder=await root.getDirectoryHandle('frameslice-edit-'+crypto.randomUUID(),{create:true});const file=files.value[0];await workspace.run('remux',file,ctl.signal,ctx=>runContainerInWorker({file,folder,action:mode.value,format:'mp4',selectedIds:[],acknowledgeUnlisted:false,range:{start:start.value,end:end.value},mergeFiles:[...files.value],allowAacPreroll:allowAacPreroll.value},ctl.signal,{onProgress:(p,l)=>{progress.value=p;message.value=l;ctx.progress(p,l)},onOutput:o=>{result.value.push(o);ctx.checkpoint(o.filename)}}));message.value='处理及深度校验完成';progress.value=1}catch(e){error.value=friendlyError(e)}finally{busy.value=false;ctrl=null}}
onBeforeUnmount(()=>ctrl?.abort())
</script>
<template><section class="fs-analysis"><div class="fs-analysis-header"><strong>无损剪辑与合并（实验功能）</strong><WorkbenchSelect v-model="mode" label="剪辑方式" :disabled="busy" :options="([{value:'trim',label:'区间截取'},{value:'merge',label:'顺序合并'}] as const)" @update:model-value="files=[];result=[]"/></div><p class="fs-analysis-disclaimer">{{mode==='trim'?'先分析安全 GOP 索引，再选择区间或主动吸附；不重新编码。':'支持同配置单视频轨、最多八条音轨；音视频必须完整对齐，内嵌字幕不支持复制，AAC 前置包需显式选择兼容处理；即使逐包校验通过，解码接缝也可能与独立播放波形不同。'}}</p><button class="secondary-button" :disabled="busy" @click="pick">选择{{mode==='merge'?'多个':''}}视频</button><div v-for="(file,i) in files" :key="i" class="fs-job-row"><strong>{{i+1}}. {{file.name}} · {{humanBytes(file.size)}}</strong><div v-if="mode==='merge'"><button class="secondary-button" :disabled="busy||i===0" @click="move(i,-1)">上移</button><button class="secondary-button" :disabled="busy||i===files.length-1" @click="move(i,1)">下移</button></div></div><div v-if="mode==='trim'" class="fs-center-toolbar"><button class="secondary-button" :disabled="busy||analyzing||!files.length" @click="analyze">{{analyzing?'分析中…':'分析关键帧边界'}}</button><span v-if="duration">{{keys.length}} 个安全切割边界 · {{duration.toFixed(3)}} 秒</span><label>起始秒 <input v-model.number="start" type="number" step="any" min="0" :disabled="busy"/></label><label>结束秒 <input v-model.number="end" type="number" step="any" min="0" :disabled="busy"/></label><button class="secondary-button" :disabled="busy||!keys.length" @click="snap('start')">吸附起点</button><button class="secondary-button" :disabled="busy||!keys.length" @click="snap('end')">吸附终点</button><input v-if="keys.length" type="range" min="0" :max="duration" step=".001" v-model.number="start" @change="snap('start')" aria-label="截取起点"/><input v-if="keys.length" type="range" min="0" :max="duration" step=".001" v-model.number="end" @change="snap('end')" aria-label="截取终点"/></div><WorkbenchCheckbox v-if="mode==='merge'" v-model="allowAacPreroll" :disabled="busy"> 允许剔除每条音轨播放区间外的单个完整 AAC 前置包（可能影响接缝解码，不保证逐采样一致）</WorkbenchCheckbox><button v-if="!busy" class="primary-button" :disabled="analyzing||files.length<(mode==='merge'?2:1)||(mode==='trim'&&!validRange)" @click="run">选择目录并执行</button><button v-else class="secondary-button" @click="ctrl?.abort()">取消</button><p role="status">{{message}}</p><progress v-if="busy" :value="progress" max="1"/><p v-if="error" role="alert" class="fs-analysis-warning">{{error}}</p><p v-for="item in result" :key="item.filename">{{item.filename}} · {{humanBytes(item.bytes)}}<span v-if="item.excludedAacPreroll?.packets"> · 已明确剔除 {{item.excludedAacPreroll.packets}} 个 AAC 前置包</span></p></section></template>
